        saved &&
        typeof saved === "object" &&
        "title" in saved &&
        "markdown" in saved &&
        typeof saved.title === "string" &&
        typeof saved.markdown === "string"
      )
        return saved;
    } catch {
      /* Start with an empty form if storage is unavailable. */
    }
    return { title: "", markdown: "" };
  });
