  const errors = [];
  page.on('pageerror', error => errors.push(error.message));
  await page.goto('http://localhost:5173');
  const input = page.getByLabel('Текст заметки', {exact:true});
  const preview = page.getByRole('region', {name:'Предпросмотр Markdown'});
  await input.fill('## Заголовок\\n\\n**Жирный** и *курсив* и ~~удалено~~\\n\\n- пункт один\\n- пункт два\\n\\n> Цитата\\n\\n[Ссылка](https://example.com)\\n\\n"'```js'"\\nconst x = 1;\\n"'```'"\\n\\n| A | B |\\n|---|---|\\n| 1 | 2 |\\n\\n- [x] готово');
  assert.equal(await preview.locator('h2').textContent(), 'Заголовок');
  assert.equal(await preview.locator('strong').textContent(), 'Жирный');
  assert.equal(await preview.locator('em').textContent(), 'курсив');
  assert.equal(await preview.locator('del').textContent(), 'удалено');
  assert.equal(await preview.locator('blockquote').textContent(), '\\nЦитата\\n');
  assert.equal(await preview.locator('pre code').textContent(), 'const x = 1;\\n');
  assert.equal(await preview.locator('table').count(), 1);
  assert.equal(await preview.locator('input[type=checkbox]:checked').count(), 1);
  assert.equal(await preview.getByRole('link', {name:'Ссылка'}).getAttribute('href'), 'https://example.com');
  await input.fill('выделение');
  await input.evaluate(el => el.setSelectionRange(0, el.value.length));
  await page.getByRole('button', {name:'Жирный', exact:true}).click();
  await page.waitForFunction(() => document.querySelector('#note-content').value === '**выделение**');
  assert.equal(await preview.locator('strong').textContent(), 'выделение');
  await input.fill('курсив');
  await input.selectText();
  await input.press('Control+i');
  assert.equal(await input.inputValue(), '*курсив*');
  assert.equal(await preview.locator('em').textContent(), 'курсив');
  await input.fill('<script>window.pwned=true</script>\\n\\n[опасная](javascript:alert(1))\\n\\n<img src=x onerror=\"window.pwned=true\">');
  assert.equal(await preview.locator('script').count(), 0);
  assert.equal(await preview.locator('[onerror]').count(), 0);
  assert.ok("'!(await preview.locator('"'a').getAttribute('href')).startsWith('javascript:'));
  assert.equal(await page.evaluate(() => window.pwned), undefined);
  await input.fill('');
  assert.equal(await page.locator('.empty-preview').count(), 1);
  await page.getByRole('button', {name:'Подсказки'}).click();
  assert.equal(await page.locator('#markdown-help').isVisible(), true);
  await page.getByRole('button', {name:'Скрыть подсказки'}).click();
  await page.getByRole('button', {name:'Вставить пример'}).click();
  assert.ok((await input.inputValue()).includes('**одной простой мысли**'));
  assert.equal(await preview.locator('strong').textContent(), 'одной простой мысли');
  await page.getByLabel('Название', {exact:true}).fill('Моя заметка');
  await page.getByRole('button', {name:'Сохранить заметку'}).click();
  assert.match(await page.getByRole('status').textContent(), /сохранена/);
  const value = await input.inputValue();
  await page.reload();
  assert.equal(await input.inputValue(), value);
  assert.equal(await page.getByLabel('Название', {exact:true}).inputValue(), 'Моя заметка');
