  await page.screenshot({path:'/tmp/markdown-mobile.png',fullPage:true});
  assert.deepEqual(errors, []);
  console.log('PASS: live Markdown, GFM, selection formatting, keyboard shortcut, safe HTML/URLs, empty state, help, example, save/reload, mobile layout, no browser errors.');
